from pathlib import Path
import base64, zlib, hashlib

JS_Z64 = ''''''
CSS_Z64 = ''''''

EXPECTED = {
    'dist/assets/hf32-public.js': '11f104253eb55bfb38d880f313fa60008e7097626526aefa355e6945a2eadf5c',
    'dist/assets/hf32-public.css': '485946a5cea4faa19acc9ca8a2addd342246b4cd7c59e8811b2e33ffb61d38c0',
}

for path, payload in [('dist/assets/hf32-public.js', JS_Z64), ('dist/assets/hf32-public.css', CSS_Z64)]:
    data = zlib.decompress(base64.b64decode(payload))
    digest = hashlib.sha256(data).hexdigest()
    if digest != EXPECTED[path]:
        raise SystemExit(f'hash mismatch for {path}: {digest}')
    out = Path(path)
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_bytes(data)

r37 = Path('dist/assets/r37-i18n.js')
text = r37.read_text(encoding='utf-8')
marker = '/* HF3.2 — owner-approved simplification layer. */'
if marker not in text:
    text += """

/* HF3.2 — owner-approved simplification layer. */
(()=>{
  function load(){
    if(document.querySelector('script[data-hf32-public]'))return;
    const js=document.createElement('script');
    js.src='/assets/hf32-public.js';
    js.defer=true;
    js.dataset.hf32Public='1';
    document.head.append(js);
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',load,{once:true});else load();
})();
"""
    r37.write_text(text, encoding='utf-8')

print('HF3.2 assets materialized and r37 loader updated')
